List<string> Weg(string start, string ziel)
{
    var vorg = new Dictionary<string, string>
        { [start] = null };
    var q = new Queue<string>();
    q.Enqueue(start);
    while (q.Count > 0)
    {
        string k = q.Dequeue();
        if (k == ziel) break;
        foreach (string n in g[k])
            if (!vorg.ContainsKey(n))
            {
                vorg[n] = k;
                q.Enqueue(n);
            }
    }
    if (!vorg.ContainsKey(ziel)) return null;
    var weg = new List<string>();
    for (string k = ziel; k != null;
         k = vorg[k])
        weg.Add(k);
    weg.Reverse();
    return weg;
}
Console.WriteLine(
    string.Join(" -> ", Weg("D", "F")));
// D -> B -> E -> F

